import type { Story } from "./stories";

export const stories2200: Record<number, Story> = {
	2200: {
		index: 2200,
		text: `<p>The other swells at your kind words and offers and leads you to a dark alley to converse further. There, the other has more friends waiting to "discuss" matters with you.</p>
<p><b>No Skill:</b> They satisfy themselves with merely robbing you blind. [S1/W-1 (Min: Penniless)]</p>
<p><b>Weapon Use:</b> With flashing blade, you beat your way clear of the ambush and barely escape pursuit. [D1/S2]</p>
<p><b>Stealth and Stealing:</b> You acquiesce to being roughly searched but manage to conceal the bulk of your coins. During the treatment you even manage to palm a few extra from your would-be robbers. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	2201: {
		index: 2201,
		text: `<p>The other looks at you, a sneer on their face. "And who are you to speak to me so? I don't need your wares or your assistance."</p>
<p><b>No Skill:</b> The other is not convinced by your complimentary words and leaves you swiftly. However, another witnesses your humiliation and spreads the tale throughout town. [D-1/S1/<em>Scorned</em>]</p>
<p><b>Acting and Disguise:</b> You manage to fool the other into thinking you travel in the same circles. After spending a few nights at their side you realize the other is not possessed of all their faculties. Not to waste any more time dealing with this person, one night you slip away into the dark, thanking Allah for your wits. [D1/S2]</p>`,
	},
	2202: {
		index: 2202,
		text: `<p>You woo the other with silvered words, offering aid and good deals.</p>
<p><b>No Skill:</b> The other rewards you with a coin before dismissing you to be on with their own story. [D1/W+1 (Max: Poor)]</p>
<p><b>Beguiling:</b> They take you into their confidence and after a short time show you a secret map that has come into their possession. [D1/S1/Opportunity to enter the Cave of Wonders]</p>`,
	},
	2203: {
		index: 2203,
		text: `<p>Your detailed schemes always seem to end badly, so when an opportunity presents itself, you follow your instincts. With a quick blow, you knock out your victim and then drag him to an empty home nearby.</p>
<p><b>No Skill:</b> All seems well until the members of the household return. You are able to escape, but your face has been seen by many. [S1/<em>Outlaw</em>]</p>
<p><b>Luck:</b> The house belongs to a merchant who is away on business. This allows you to conduct the ransom negotiations without interference, bringing you a nice profit. [W+2 (Max: Rich)]</p>`,
	},
	2204: {
		index: 2204,
		text: `<p>You are unable to penetrate the wall of guards surrounding your intended victim. The only person that seems to have personal access to the other is an old woman, the other's personal soothsayer. The other, always in fear of losing his fortune, needs his future foretold constantly, as a way of reassurance.</p>
<p><b>No Skill:</b> It's an interesting bit of information but not one you can make use of. [S1]</p>
<p><b>Acting and Disguise:</b> This gives you an idea. You follow the old woman for a week, studying her mannerisms. One evening you knock her out, then dress in her clothes and make yourself up to look like her. When you go to see the other, you tell him that he will find a hidden fortune at a place near the city, but only if he goes there alone at dusk. The other follows your "prophecy," and you are there waiting for him. [W+3 (Max: Princely)/Enduring Hardship/<em>Determined</em>]</p>`,
	},
	2205: {
		index: 2205,
		text: `<p>The riches of the other's household motivates you to plan a kidnapping.</p>
<p><b>No Skill:</b> It turns out to be an easy matter to abduct the other—but getting money for the other is another matter. The other tells you that you have accomplished what members of the household wished for. This angers you and together you plot to abscond with the household riches using the other's knowledge of secret ways into the house. [D1/W+3 (Max: Rich)]</p>
<p><b>Wisdom, Acting and Disguise:</b> The deed is done, but what's this? You notice some mannerisms on your victim not seen before. You discover him to be an imposter, a decoy—a double! You will not receive any money today and must quickly leave the city. [Enduring Hardship/<em>Outlaw</em>]</p>
<p><b>Determined</b> [mandatory], <b>Luck:</b> The other turns out to have a gambling problem so your plan will now be less risky. You are able to get into the graces of people he gambles with and with a few hours, you have taken a fortune from him! [W+4 (Max: Princely)/Quick Thinking]</p>
<p><b>Seduction</b> [if opposite sex]: Why kidnap when you can seduce? You work your way into the other's favor. Soon you are married and share in the other's wealth and want for nothing. [S1/W+3 (Max: Rich)/<em>Married</em>]</p>`,
	},
	2206: {
		index: 2206,
		text: `<p>The wicked Vizier of this land has ordered the other to be displayed publicly in a cage, that all might witness his power. As you walk by this prison, the other tries to whisper to you, but you do not wish to gain the Vizier's disfavor. You continue walking, ignoring the pleading whispers. [D1]</p>`,
	},
	2207: {
		index: 2207,
		text: `<p>A string of slaves walk toward the market to be sold. One among the slaves stands out for his dignified bearing. You consider investigating the story behind that one's enslavement, but decide instead to leave well enough alone. [S1]</p>`,
	},
	2208: {
		index: 2208,
		text: `<p>After finishing some unsavory business with a jailor to fulfill an old debt, you pass by a dungeon door wherefrom thin, pale hands protrude. You consider inquiring about the prisoner, but the gloomy interior of the dungeon is bringing you to sorrow, and instead you hasten to be outside. [D-1]</p>`,
	},
	2209: {
		index: 2209,
		text: `<p>As you pass through dense woods, you discover that all around you are the remains of a vast, ruined city, deserted long ago. Now, nowhere do you find two stones that still stand atop each other, until in a small clearing you find a stone obelisk, graven with strange symbols.</p>
<p><b>No Skill:</b> You cannot read the symbols, and depart unsatisfied. [S1]</p>
<p><b>Scholarship:</b> The language is ancient, but known to you. You learn what you can and when you come to the nearest town, you make sure that word of your discovery is made known to the prince of this region. [D1/S1]</p>`,
	},
	2210: {
		index: 2210,
		text: `<p>Certain signs tell you that the ruins of a lost city are in the area. Although you do not wish to explore them yourself, when you come again to civilization, you seek out a scholar you know. He is quite interested in your tale and hastens off to find out more of your marvelous discovery. [S1]</p>`,
	},
	2211: {
		index: 2211,
		text: `<p>As you ride along a high hillside, you see through the canopy of a forest below you unmistakable signs of a once-proud city now in ruins. You are in amazement, but you can see no way to get down into the valley unless you were to sprout wings. With a sigh, you head onward to your destination. Perhaps this is the closest you were ever intended to come to it? [S1/Lose <em>Fated</em>]</p>`,
	},
	2212: {
		index: 2212,
		text: `<p>Despite their reduced circumstances, the other sees through your trick almost immediately. "You are beneath my amusement, but perhaps my guards will enjoy toying with you." The other smiles and calls out for those who guard him in prison. You turn and flee.</p>
<p><b>No Skill:</b> You are quickly caught and overpowered by the laughing guards. They make good sport of thrashing you into a pulp. [D1/<em>Crippled</em>]</p>
<p><b>Wilderness Lore:</b> You make good use of your slim lead and race into the wilds. Living off the land, a friend to all manner of beast, you lead the guard on a merry chase. After days of pursuit, while you grow fat off the land, they abandon their search. [D1/S2/Enduring Hardship]</p>`,
	},
	2213: {
		index: 2213,
		text: `<p>You spin a tale to the other, suggesting that they should aid you in their own kidnapping!</p>
<p><em>Roll one die, adding one each for Luck, Beguiling, and Storytelling:</em></p>
<p><em>1–3:</em> The other is insulted by your attempt to fool them. The other will not help you free them from one prison only to be put into another! [D1/S1]</p>
<p><em>4+:</em> The other is convinced and surprises you greatly. He already has a key to open his shackles! [D1/S2/Storytelling/<b>One Hundred Keys</b>]</p>`,
	},
	2214: {
		index: 2214,
		text: `<p>While his captor is away, you catch the other's attention. Engaging them in conversation you seek to learn the plans they foster and the circles they travel in. You decide that this prisoner would bring in a hefty ransom.</p>
<p><b>No Skill:</b> You unbind and rebind the other, whisking him away to question further. The other reveals very little, but the wrestling match of words proves very educational. You eventually release him, for no one ever offers any reward. [D1/S2/Storytelling]</p>
<p><b>Beguiling:</b> You are successful in your kidnapping but no one ever claims him. You eventually let him go, but not before he has enriched you with many stories of his travels. [D1/S3/Opportunity to enter any Place of Power]</p>`,
	},
	2215: {
		index: 2215,
		text: `<p>Filled with bravado, you draw your blade and boldly demand payment from the other.</p>
<p><b>No Skill:</b> The other's eyes go wide in disbelief. You are robbing someone who is in chains? The other laughs heartily, wounding your pride. [D2/S1/<em>Grief Stricken</em>]</p>
<p><b>Weapon Use:</b> Seeing the surety of your grip, the other cries out for the guards to deal with you. With swift steel you strike down the guards and repeat your original demand. Amazed that you knew he had something hidden from his captors, he pulls it out from inside his robes for you. [D1/S2/<b>Treasure</b>]</p>`,
	},
	2216: {
		index: 2216,
		text: `<p>Girding yourself, you draw steel and demand the other surrender their coins or their life. With an exaggerated roll of his eyes, the other dismisses your threat. You can't seriously be robbing someone in chains!</p>
<p><b>No Skill:</b> To your amazement, the captor is schooled in the ways of magic. You feel his incantation warp your body and mind, leaving you dazed and changed. The touch of magic leaves its mark upon you. [S2/Magic/<em>Beast Form</em>]</p>
<p><b>Magic:</b> You sense immediately that the other has some small amount of magical abilities. You counter the other's magic with your own potent spells. The other convinces you that you should free him that you both might engage in a test of wills—a duel of sorcery. Your battle is witnessed, and even though in the end you are defeated by a foe whose respect you have earned, the story of your might spreads. [D1/S2/<em>Respected</em>]</p>`,
	},
	2217: {
		index: 2217,
		text: `<p>Despite all common sense, lust for the other's wealth compels you to rob him. Half-crazed by greed you assault the other, grasping for what you hope will be treasures.</p>
<p><b>No Skill:</b> Enraged, the other buffets you with a mighty blow of their chains, dashing what little sense you had left from you. When you come to, you are no longer sure where you are, or even who. [<em>Lost</em>/<em>Wounded</em>]</p>
<p><b>Enduring Hardship:</b> You awake sometime after the other cuffs you into a daze. The number of days you lay on the side of the road refuses to come to you. You wander the land until your senses return. [<em>Insane</em>/<em>Lost</em>]</p>`,
	},
	2218: {
		index: 2218,
		text: `<p>In the home of a distant cousin, you come across the other. Not wishing to transgress on your family hospitality, you resolve to ask about it in the morning. But when morning comes, there is no sign of the door, nor do any of your kin know whereof you speak. What a puzzle! [S1]</p>`,
	},
	2219: {
		index: 2219,
		text: `<p>You came by chance to stand before this door. There is no marking on it to indicate what is beneath it, but nor is there anyone in sight to stop you from opening it. As you place your hand on the pull, you pray for guidance... and cannot bring yourself to open it. You head on your way, wondering what Allah has in store for you next. [Piety]</p>`,
	},
	2220: {
		index: 2220,
		text: `<p>In this fierce land, you cannot imagine anything good which could be sealed behind such a barrier. You give a wide berth to the other, and head on your way. [D1]</p>`,
	},
	2221: {
		index: 2221,
		text: `<p>With scorn on your face, you attack your hapless foe.</p>
<p><b>No Skill:</b> They flee from you, a cry on their lips. The other is adept at the ways of the wild and evades your pursuit. You must assuage your rage another day. [D-2]</p>
<p><b>Wilderness Lore:</b> The other flees into the wilds, you hot on their trail. After a day's chase you corner the other in a lonely mountain pass. They are too exhausted to put up a fight and are easily slain. [D-1/W+1 (Max: Poor)]</p>`,
	},
	2222: {
		index: 2222,
		text: `<p>The other's hapless condition moves you to anger.</p>
<p><b>No Skill:</b> You berate them mercilessly, hoping to shame them into respecting themselves more. The silence of the other leaves you with the hope that they may have heard you. Sometime later your paths cross again. By virtue of hard work and determination, the other has come back to an honorable position, and they heap rewards upon you for your help. [D2/S2/W+1 (Max: Rich)]</p>
<p><b>Scholarship:</b> You cuff them repeatedly while berating them for the condition they have gotten themselves into. The weight of your words strikes truer than your blows and they break into a tumult of tears and swear to heed your words. A crowd observes your treatment of the other, and spread the tale of the wisdom of your words. [D2/S1/<em>Respected</em>]</p>`,
	},
	2223: {
		index: 2223,
		text: `<p>Sensing your strength, you draw your weapon and attack.</p>
<p><b>No Skill:</b> The other fights with the power of ten men. You are desperate to force your opponent into a corner. The fight gathers a crowd and with luck, the other trips over one of the spectators. You press the advantage. [S2/Weapon Use]</p>
<p><b>Weapon Use:</b> The other's strength catches you off guard, but your skills triumph. As you stand over your slain foe, you realize that you have gained great skill. [D1/Weapon Use]</p>`,
	},
	2224: {
		index: 2224,
		text: `<p>Despite your misgivings you decide to engage the other in conversation.</p>
<p><b>No Skill:</b> The other's tale winds across black and desolate vistas. After a day and a night of raving the other wanders away, leaving you lost and hopelessly confused. [D1/S2/<em>Insane</em>]</p>
<p><b>Enduring Hardship:</b> The other's tale of woe and despair blackens your heart. As the tale crawls to a fevered pitch, the other works into a frenzy of depression. You watch, horrified, as they leap to their doom into a deep gorge, leaving you stricken. [S2/<em>Grief Stricken</em>]</p>`,
	},
	2225: {
		index: 2225,
		text: `<p>The other regales you with tales of their dark visions.</p>
<p><b>No Skill:</b> Long before the other is done with their tale you realize how much of your time has been wasted with nothing to show for it. [D1]</p>
<p><b>Scholarship:</b> From the depth of the other's story a pattern begins to emerge. From it you discover clues that lead to an ancient dark ruin. [D1/S2/Opportunity to enter the Haunted House]</p>`,
	},
	2226: {
		index: 2226,
		text: `<p>With good humor you listen to the other's tale. It lasts long into the night.</p>
<p><b>No Skill:</b> As the light of dawn cracks over the horizon, the other finally slumps to peaceful rest and you are able to quietly escape. The other's tale, though filled with gloom, contains a few useful gems for your next tale-telling. [S1/Storytelling]</p>
<p><b>Scholarship:</b> Although the tale is long and painful, the other's woes and terrible prophecies reveal the source of their gloom and its place of origin. [S2/Opportunity to enter the Haunted House]</p>`,
	},
	2227: {
		index: 2227,
		text: `<p>Seeing in the other great wisdom beneath their prophecies of catastrophe, you strive to court their favor.</p>
<p><b>No Skill:</b> You spend time in discourse with the other, and listen to long rants on the oncoming doom of the world. In between the tales of inevitable destruction, and undeniable horror, you manage to pry free some gems of wisdom. [S1/Scholarship]</p>
<p><b>Wisdom:</b> The tumult of gloom that continuously pours from the other abounds with bits and pieces of a moral tale worthy of the ages. After the long hours of ranting are concluded, you go off to ponder your fate and you are strangely left with uplifted spirit. [D2/S1/<em>Determined</em>]</p>`,
	},
	2228: {
		index: 2228,
		text: `<p>Despite the other's terrible predictions, and seemingly tireless enthusiasm to espouse them, you see in them something worthy of audience.</p>
<p><b>No Skill:</b> Amidst the other's rants and predictions, there is mention of a holy hermit and the location of his cave. Curious to see what kind of holy man might lead to such an outlook, you set your sight on visiting the man. [D1/<em>On Pilgrimage</em>]</p>
<p><b>Enduring Hardship:</b> Encouraged by your attention, the other hounds your steps for days on end. In order to not subject random strangers to the other's gloom, you head into the wilderness. In short order the hardships prove too much for the other and they beg you to lead them back to civilization. You are rewarded by a strained half-smile and unenthusiastic "thank you," when you part ways. [D2/S1]</p>`,
	},
	2229: {
		index: 2229,
		text: `<p>Despite common sense, you decide that the other has some wisdom to offer behind their doom-heavy words. The other is grateful for the attention and decides to accompany you. They loudly proclaim catastrophe to you and anyone who is unlucky enough to cross your path. You are scorned until you can be rid of the other. [D1/<em>Scorned</em>]</p>`,
	},
	2230: {
		index: 2230,
		text: `<p>The relentless tale of the other's many piteous turns dulls your better judgment.</p>
<p><b>No Skill:</b> You cannot take the other's condition as is and decide the proper cure is riches, and you press your purse on the other and flee. When you cross paths again a few weeks later, nothing has changed—your generous endowment was quickly frittered away. [D2/W-2 (Min: Poor)]</p>
<p><b>Luck:</b> Despite the obvious path of the other's life, you decide to try to relieve their condition. But the other seems not able to change their station in life and has soon spent the whole of your generous offer. Luckily you are able to gamble on a risky local caravan, and soon recoup most of your losses. [D2/W-1 (Min: Poor)]</p>`,
	},
	2231: {
		index: 2231,
		text: `<p>The other's wretched condition cannot help but stir you to compassion.</p>
<p><b>No Skill:</b> Your offer of conversation is ignored but your offer of coin is gratefully accepted by the other. However, from the greed in their eyes, and the way they snatch the coins before hurrying off lets you know they will not have their new wealth for long. The lesson is not lost on you. [D2/S1/W-1 (Min: Rich)]</p>
<p><b>Respected</b> [mandatory]: Your caring for the other is observed. The witnesses are moved by your example, and rush to aid the other as well. With very few coins leaving your purse, the other is restored to a respectable status. [D2/S1/<em>Respected</em>]</p>`,
	},
	2232: {
		index: 2232,
		text: `<p>You cannot help but be moved by the other's tale of the woes that lead them to their current situation.</p>
<p><b>No Skill:</b> The other is stirred by your compassion and swears by Allah that they will not squander your kindness. [D1/Piety]</p>
<p><b>Wisdom:</b> Truly it is said, "Alms now are a meal now, but true wisdom is a meal forever." The other heeds your wise words and follows your guidance. In short order their situation is put to rights and they are once again on the road to self-sufficiency. For the rest of their days they vow to assist you where they may. [D2/<em>Blessed</em>]</p>`,
	},
	2233: {
		index: 2233,
		text: `<p>People are aghast that you would attack such a fair being. A crowd gathers to subdue you.</p>
<p><b>No Skill:</b> You are grabbed and beaten. [D1/W-2 (Min: Poor)/<em>Wounded</em>]</p>
<p><b>Beguiling:</b> Before they can enact any revenge on you, you make an impassioned speech about how beauty of the heart is the only true beauty. The crowd is pacified and lets you go. [D1/S1/Quick Thinking]</p>
<p><b>Storytelling:</b> You quickly tell the crowd that the other has used beauty to beguile you and should be punished. You are so convincing that the crowd carries the other off to the beating you should have received. Pondering your actions brings you no comfort. [S1/<em>Grief Stricken</em>]</p>`,
	},
	2234: {
		index: 2234,
		text: `<p>You draw your weapon and advance—no pause in the face of such beauty.</p>
<p><b>No Skill:</b> Before you can strike you are dumbstruck by the other's visage. You drop your weapon and beg to be forgiven. The other recommends that you take up a journey of forgiveness. [D1/<em>On Pilgrimage</em>]</p>
<p><b>Appearance:</b> You have no soft spot for the Beautiful—you know what can truly lie in their hearts. The other is easily defeated. [S1]</p>`,
	},
	2235: {
		index: 2235,
		text: `<p>Caught by surprise, the other stumbles to get away. You give chase, easily catching the other, and the deed is quickly done. Gazing upon your hapless victim, you are overtaken with sadness. [D1/<em>Grief Stricken</em>]</p>`,
	},
	2236: {
		index: 2236,
		text: `<p>Despite the other's haughty nature, you cannot help but dote on them. After sometime of waiting on the other hand and foot, you overhear your love joking with their friends about your slavishness and what a fool you are.</p>
<p><b>No Skill:</b> In shame you leave and travel far away to nurse your broken heart. [D1/<em>Grief Stricken</em>]</p>
<p><b>Luck:</b> The other continues by confessing their star-struck love to another. Deciding to take the hint you abandon your chosen post, but not before divulging the other's pathetic infatuation to the object of their desire. You leave them despondent and they occasionally make attempts at revenge on you. [D1/S2/<em>Pursued</em>]</p>`,
	},
	2237: {
		index: 2237,
		text: `<p>Stricken by the other's beauty, you rush to offer your services. However, the other's life is a constant whirl of parties, admirers, and courtiers.</p>
<p><b>No Skill:</b> You spend some days in their orbit, but are never able to get more than a generous smile and friendly glance. Soon you take your leave, having learned something of the ways of polite society. [S1/Courtly Graces]</p>
<p><b>Courtly Graces:</b> With adroit diplomacy, and silver tongue you help to smooth their way for a time. From the experience you garner their favor and a host of useful connections. [D1/S2/W+1 (Max: Princely)]</p>`,
	},
	2238: {
		index: 2238,
		text: `<p>You gallantly offer your services to the other, in the hopes of basking in their beauty for a while longer.</p>
<p><b>No Skill:</b> The other makes good use of your talents for sometime before graciously releasing you from your bonds of the heart. The parting is bittersweet, but righteous. You set back out on your adventures with a renewed sense of purpose. [D1/S1/Enduring Hardship]</p>
<p><b>Seduction:</b> In a fortnight the other has completely surrendered to your charming graces. Early the next season you find yourself in wedded bliss. [D1/S2/<em>Married</em>]</p>`,
	},
	2239: {
		index: 2239,
		text: `<p>Enraged by the other's aggressive begging, you decide to press them into service.</p>
<p><b>No Skill:</b> You endure the other's terrible service for a short time before waking one morning to find them gone, along with several of your coins. [W-1 (Min: Poor)]</p>
<p><b>Quick Thinking:</b> The other begrudgingly does your bidding for a time. Not one to be lulled into absent-mindedness, you keep one eye always on the other. You catch them one night trying to slip coins from your purse. With a sound beating you chase them off. [S1]</p>`,
	},
	2240: {
		index: 2240,
		text: `<p>The other may appear to be a wretch, but their worn appearance does not stop you from recognizing them as a member of a well-to-do family. You take the other into your care, against their protests. You notify the other's family, and offer to return them for a modest reward.</p>
<p><b>No Skill:</b> Your efforts are met with cold reception, and the family takes the case to the local emir. You are taken into custody for your troubles. [S1/<em>Imprisoned</em>]</p>
<p><b>Courtly Graces:</b> Your well-worded letter to the other's family, pleading the case of the other's condition adroitly, is equally well-received. The family gratefully takes the other back, rewarding you for your troubles. [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	2241: {
		index: 2241,
		text: `<p>Determined to teach the other how to reform their ways, you press them into your service and take them into your tutelage.</p>
<p><b>No Skill:</b> The other serves you and takes your advice, but begrudgingly. After some weeks you release them after receiving their promise to reform their ways. [D1/S1]</p>
<p><b>Scholarship:</b> While holding the other to your service, you do your best to show by example the possibilities of a well-lead life. When the other is finally able to stand on their own feet, they depart to establish their own place in the world. Their example renews your own vigor. [D2/S1/<em>Determined</em>]</p>`,
	},
	2242: {
		index: 2242,
		text: `<p>With a sly wink to the other, you lean forward and whisper that you can be of aid to the other.</p>
<p><b>No Skill:</b> The other becomes enraged that you have endangered their disguise. You find yourself swiftly on the losing end of a severe beating. [<em>Wounded</em>]</p>
<p><b>Enduring Hardship:</b> The other is gravely insulted that you would so readily ruin their disguise. You find yourself swiftly on the grim end of a sound beating. But you've had a great deal worse. [S1]</p>`,
	},
	2243: {
		index: 2243,
		text: `<p>Assuming the other must have a sly plan afoot, you openly beg to be let in on the deal.</p>
<p><b>No Skill:</b> You fail to impress the other and they swiftly leave to be about their mysterious work abandoning you to ponder. [S2]</p>
<p><b>Seamanship:</b> As luck would have it, the other is in desperate need of an incognito journey to a distant island kingdom to woo the favors of a forbidden love, and for this trip they will reward you handsomely. The journey takes you to strange lands indeed. [D1/S2/W+1 (Max: Rich)/Opportunity to enter any Place of Power]</p>`,
	},
	2244: {
		index: 2244,
		text: `<p>Seeing the effort the other has gone to, you assume there must be riches to be had. Desperate for coin you implore the other to allow you to aid them for a modest share.</p>
<p><b>No Skill:</b> The other silences you with a hard stare. Quickly looking about to find if you have undone the disguise, the other grabs you firmly by the arm and drags you to a hidden location. They let you in on their plan in all its intricacies and too they tell of the enormous reward awaiting at its completion. Your part is to observe one of the side gates of a local merchant's compound. It takes a full day, and most of a night before you realize you have been sent on a wild goose chase while the other carries out whatever their real work was. [S2]</p>
<p><b>Acting and Disguise:</b> The other whisks you to a hidden location to speak with you unheard. After learning the plan, you list the many ways in which you could be of use. The other settles on disguising you to play the part of an advisor during their complicated plot to wrest gold from a local merchant.</p>
<p><em>Roll one die, adding one each for Beguiling, Quick Thinking, and Courtly Graces.</em></p>
<p><em>1:</em> The merchant has been alerted to your plot. Barely have you entered the compound when the gates swing shut behind you and a host of guards rush to greet you. [D-1/S1/<em>Imprisoned</em>]</p>
<p><em>2–3:</em> The merchant is highly suspicious of the whole situation, having been warned that something may be afoot. With quick tongue, you craft an offer of obtaining proof of the other's veracity. The merchant allows you to leave to fetch the evidence. You flee the region, never looking back. The other manages to extricate themselves as well and vows vengeance. [S2/<em>Pursued</em>]</p>
<p><em>4–6:</em> You play your part well enough, but the merchant is highly suspicious. As an alarmed look from the other, you weave an excuse for delaying the dealings for another day. Under the watchful scowl of the merchant, you and the other escape to scheme another day. The other is grateful for your intervention. They reward you and remember you fondly till their dying day. [D1/S2/W+1 (Max: Rich)/<em>Respected</em>]</p>
<p><em>7–8:</em> The merchant is taken in by the plot, cautiously. They are not caught as much as the other would have liked. With quick words you smooth the conversation, and the plot succeeds. The merchant is soon substantially poorer, while you enjoy your portion of the fleecing. [D1/S2/W+2 (Max: Princely)]</p>
<p><em>9:</em> The merchant is pulled into the plan, hook, line, and sinker. While the other deals with the elaborate preparations of the false caravan the merchant is being hooked into backing, you manage to slip away and dig through the compound's storehouse. You find many loose coins and treasures, and a very interesting map. [S2/W+2 (Max: Princely)/<b>Treasure</b>/Opportunity to enter the Valley of Diamonds]</p>`,
	},
	2245: {
		index: 2245,
		text: `<p>You realize the other is not as they seem. Seeing a chance for rewards, you decide to hold and force them to reveal themselves and their purpose for the disguise.</p>
<p><b>No Skill:</b> The other refuses steadfastly to reveal their secret, but to buy your compliance they offer you some small coin. [S1/W+2 (Max: Respectable)]</p>
<p><b>Magic:</b> Despite the other's refusal to reveal themselves, your command of magical forces peels the disguise away from your sight. The other bargains mightily for you to hold your tongue. You leave the encounter very well-rewarded indeed. [D1/S1/W+2 (Max: Princely)/<b>Giant Diamond</b>]</p>`,
	},
	2246: {
		index: 2246,
		text: `<p>The other's disguise fails to fool you.</p>
<p><b>No Skill:</b> You snatch the other away to a remote locale, and rip away their disguise. Once their true identity is revealed you demand coins to keep your tongue still about their secret. [D1/W+1 (Max: Rich)]</p>
<p><b>Outlaw</b> [mandatory]: Acting swiftly when opportunity arises, you seize the other. With your underworld connections you are able to deliver them into the hands of another scoundrel more versed in the particulars of the fine art of kidnapping. In exchange, you are let in for a generous cut of the reward. [S2/W+2 (Max: Princely)]</p>`,
	},
	2247: {
		index: 2247,
		text: `<p>You see through the other's disguise and decide to hold them for reward. But the other is not acting alone.</p>
<p><b>No Skill:</b> Their guard, disguised as a fruit vendor, takes objection to your audacity and soundly beats you before the other moves on about their business. [D-1/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> With your blade in hand, you manage to fight your way free and escape. [S1]</p>`,
	},
	2248: {
		index: 2248,
		text: `<p>You decide to engage the other in conversation, trying to soothe their seemingly endless worries and woes.</p>
<p><b>No Skill:</b> The other's circular tale of self-evident doom and destruction bewilders you with its intricacies. You leave the encounter horribly confused. [D1/<em>Insane</em>]</p>
<p><b>Wisdom:</b> It quickly becomes obvious that the other's derangement is deep beyond recovery. Your discretion wins out, and you sadly leave them to their ravings. [D1/S1]</p>`,
	},
	2249: {
		index: 2249,
		text: `<p>Your better nature moves you to wish to be of use to the other as they relentlessly spew their dark words. When the local guard comes to shoo the other away, you accompany the other to be sure they are safe for the night. The other lives in a mean hut on the outskirts of the city under the foulest of conditions.</p>
<p><b>No Skill:</b> The night passes roughly, with no sleep for you. As you leave the other the next day, you find yourself feeling less and less healthy. [D1/<em>Diseased</em>]</p>
<p><b>Enduring Hardship:</b> You watch over the other through the night. Their sleeping words prove more eloquent than their waking rants. Amongst the tumble of tales you learn the directions to a faraway place. [D2/S2/Opportunity to enter Stonehenge]</p>`,
	},
	2250: {
		index: 2250,
		text: `<p>The other grips your arm and clings, desperately spewing a tale of woe. The speed of their chatter sets your mind to whirl, and before you know what you have done you have committed yourself to aiding them. You sit with the other into the long night as they exhaust themselves with their long gloomy tale. Despite the passion of their woe-filled story, and regardless of repeated patient prompting from you, the other never seems to get around to telling you what exactly they want you to do to aid them.</p>
<p><b>No Skill:</b> As the sun sets and the night hours grow long, the other slowly sinks into an exhausted slumber, a smile on their lips from having had a captive audience for so long. You quietly take your leave, the vast tract of the other's tale echoing through your skull. [S2/Storytelling]</p>
<p><b>Storytelling:</b> Finally, after a long monstrous yawn, the tale ends as the other collapses into deep slumber. With your voluminous knowledge of the world's tales you are able piece out valuable clues from their rant, even though their infectious gloom refuses to leave you. [S2/Storytelling/<em>Grief Stricken</em>/Opportunity to enter any Place of Power]</p>`,
	},
	2251: {
		index: 2251,
		text: `<p>Despite the other's lunatic ranting of woe and doom, they seem to have collected quite a few coins in their alms bowl. Retreating to watch the other, you wait until the sun has dropped below the line of the horizon before you make your move.</p>
<p><b>No Skill:</b> Boldly, you dash for the alms bowl, and are off before the other can stop you. Their hoarse cries attract the attention of the local guard, and you are chased out of the area and into the hills. [S1/W+1 (Max: Rich)]</p>
<p><b>Stealth and Stealing:</b> You bide your time, and when the other goes to retrieve some water you nonchalantly saunter by and sweep the overflowing bowl into your robes when no one is looking. [W+1 (Max: Rich)]</p>`,
	},
	2252: {
		index: 2252,
		text: `<p>The other's relentless raving drives you into a rage. You draw your blade and demand to be paid for the waste of your time.</p>
<p><b>No Skill:</b> The other puts up a struggle. Your skirmish draws the attention of the local guard. The struggle leaves you the worse for the wear, but you manage to escape being imprisoned for your assault. [D-1/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> The other puts up a struggle, but they fall before your swift blade in short order. You leave with your purse slightly larger. [S1/W+1 (Max: Rich)]</p>`,
	},
	2253: {
		index: 2253,
		text: `<p>Angered by the other's incessant ranting, you decide that you deserve compensation for the time they are taking from you. Pulling free your blade, you demand payment. The other has no coins on their person. Enraged, you abduct them and look for someone to ransom them back. Unfortunately, you can find no one willing to buy the wretch's freedom.</p>
<p><b>No Skill:</b> All you get for your trouble is an endless tirade of depressing banter from the other. Finally, defeated by the unceasing worthlessness of the other, you take your leave. [D-1/<em>Grief Stricken</em>]</p>
<p><b>Acting and Disguise:</b> Fortunately, the other looks enough like a child of one of the local merchant families that, with the application of a crafty disguise, you might be able to fool them as long as the wretch remains gagged. You arrange for an exchange of the wretch for a hefty sack of coins. When the swap is made you manage to be far enough away to escape when the gag is removed and the ruse revealed. [S1/W+1 (Max: Princely)/<em>Pursued</em>]</p>`,
	},
	2254: {
		index: 2254,
		text: `<p>You recognize the other as a member of a well-to-do merchant family from a town not many days' travel away. You send a message to the family to gauge their interest in the wayward other. The family replies with an urgent plea for a safe return, and you see coins at the end of this venture. However, when you approach the other they are vehemently opposed to returning home. You decide to take matters into your own hands.</p>
<p><b>No Skill:</b> The other resists you wildly, breaking away from you and escaping into a passing crowd, never to be seen in the area again. When you inform the family they are disappointed but still grateful just to know that the other is alive. [D2/S1/W+1 (Max: Rich)]</p>
<p><b>Stealth and Stealing:</b> The other flees at your approach. But their knowledge of the local area, and the best places to hide, cannot match yours. You are able to easily follow their trail until they lay exhausted on the road side. In short order you deliver them to their overjoyed family and reap a rich reward. [D2/S2/W+1 (Max: Princely)/<em>Respected</em>]</p>`,
	},
	2255: {
		index: 2255,
		text: `<p>The other is a favorite of the prince of this region and has announced his plans to travel abroad. Soon after the other leaves, you pose as a messenger from the other's party and claim that the other has been abducted!</p>
<p><b>No Skill:</b> The prince sees though your deception and has you beaten and locked up. [S1/<em>Imprisoned</em>]</p>
<p><b>Acting and Disguise:</b> You thoroughly convince the prince and he arranges for the ransom to be paid. [W+3 (Max: Princely)]</p>`,
	},
	2256: {
		index: 2256,
		text: `<p>You recognize the other as a member of a well-to-do merchant family. Speaking for a short time you find that the other is not likely to be someone the family would want back. You decide instead to rob the other.</p>
<p><b>No Skill:</b> The other resists you but is no match for you. You take the other's money and leave. [S1/W+1 (Max: Rich)]</p>
<p><b>Courtly Graces:</b> You convince the other that you are of nobility and that you have been robbed. The other is taken by your story and gives you most of the coins in his purse. [S1/W+2 (Max: Princely)/Acting and Disguise]</p>`,
	},
	2257: {
		index: 2257,
		text: `<p>In the hopes of receiving the enchanted other's favor, you throw yourself at their feet and plead for a boon.</p>
<p><em>Roll one die, adding one each for Beguiling, Courtly Graces, Quick Thinking, Seduction, and Storytelling:</em></p>
<p><em>1–4:</em> The other waves you away dismissively and curses you for your impertinence. [<em>Accursed</em>]</p>
<p><em>5–8:</em> The other is unmoved by your plea and ignores you. [D1]</p>
<p><em>9+:</em> The other is greatly moved by your eloquent pleas. You are rewarded with a rare artifact and the secret to getting to a faraway place. [D2/S3/<b>Treasure</b>/Opportunity to enter any Place of Power]</p>`,
	},
	2258: {
		index: 2258,
		text: `<p>Your forehead touches the floor as you beg for a boon from the other. The other lifts you up. "Beg not of me, for I can do nothing in my present condition. Rather, I need to beg of you."</p>
<p><b>No Skill:</b> Alas, it's a situation you can do nothing about and you stammer an apology before moving away. [S1]</p>
<p><b>Magic:</b> You recognize the enchantment placed on the other and try to break it.</p>
<p><em>Roll one die, adding one each for Wisdom and Scholarship:</em></p>
<p><em>1:</em> The being who placed this enchantment is far stronger than you—so much so that now you are engulfed in its magic! [<em>Ensorcelled</em>]</p>
<p><em>2:</em> The enchantment is too strong and the pain on the other's face at your failure strikes you to the core. [D1/<em>Grief Stricken</em>]</p>
<p><em>3–5:</em> You lift the enchantment! The other rejoices, then grants your boon. [D1/W+2 (Max: Princely)/<b>Treasure</b>]</p>
<p><em>6+:</em> Not only do you destroy the enchantment, you are able to trace it back to its origin, a location steeped in magic and wonder. [D1/W+2 (Max: Princely)/Opportunity to enter any Place of Power]</p>`,
	},
	2259: {
		index: 2259,
		text: `<p>The alleyway you are strolling through suddenly becomes dark. Then a great gout of flame strikes in front of you; within, you see a human figure. You bow down, pleading for your life to be spared. "Please help me," moans the figure within.</p>
<p><b>No Skill:</b> There is nothing you can do: so soon as the flames appeared, now they disappear and light once again enters the alleyway. But your heart remains darkened, heavy with sorrow for the poor trapped soul. [S2/<em>Grief Stricken</em>]</p>
<p><b>Protective Talisman, Sparkling Spear:</b> Instinctively, you thrust the artifact into the flame and with a great whoosh of air the flame blows out, taking your treasure with it. Standing there is the other, who brings you to his estate and rewards you generously. [D1/S1/W+3 (Max: Princely)/<b>Treasure</b>/Lose choice of <b>Protective Talisman</b> or <b>Sparkling Spear</b>]</p>
<p><b>Fated, Enduring Hardship</b> [All mandatory]: Your immediate reaction is to jump into the flame to offer more assistance. Then, a concussive noise causes you to lose consciousness. When you awaken, you are alone and no longer in the land of Men. [D2/Move to the Dusky Land and have an immediate encounter]</p>`,
	},
	2260: {
		index: 2260,
		text: `<p>You approach the other stealthily and swipe a fist full of coins from their purse.</p>
<p><b>No Skill:</b> The other's enchantment rubs off on you with your close proximity. [S1/W+1 (Max: Rich)/<em>Beast Form</em>]</p>
<p><b>Magic:</b> As you grab for the coins you can feel the other's curse reaching out to entangle you.</p>
<p><em>Roll one die, adding one for Magic.</em></p>
<p><em>1–3:</em> The curse takes hold, but you manage to limit its duration. [D-1/S1/W+1 (Max: Rich)/<em>Beast Form</em> (1 turn)]</p>
<p><em>4–6:</em> You fight off the magic and hastily go on your way. [S1/W+1 (Max: Princely)]</p>
<p><em>7+:</em> With your mastery of sorcery you invert the purpose of the curse, blessing yourself with a small amount of luck. [D2/S1/W+1 (Max: Rich)/Luck]</p>`,
	},
	2261: {
		index: 2261,
		text: `<p>The other may be enchanted, but that makes their riches no less attractive.</p>
<p><b>No Skill:</b> The other notices your clumsy attempt to rob them of their coins. They utter a curse, powered by the enchantment wrapping them. You feel its effects grab hold as you run away with their coin purse in your hand. [D1/W+1 (Max: Rich)/<em>Accursed</em>]</p>
<p><b>Stealth and Stealing:</b> You swipe the other's purse without them being any the wiser. Later, when you are safely carrying the ill-gotten gains, you realize that some of the other's enchantment has rubbed off on the purse. [D1/S2/W+2 (Max: Princely)/<em>Ensorcelled</em>]</p>`,
	},
	2262: {
		index: 2262,
		text: `<p>You successfully dupe your victim and are enriched. However, hours later, you are beset by strange magical attacks.</p>
<p><b>No Skill:</b> In desperation you return the goods and beg the other to dispel the curse—to no avail, for the curse lingers with you. [D1/S1/<em>Accursed</em>]</p>
<p><b>Magic:</b> Your magical skills are the equal of those of your opponent. You easily defeat his curse. [D2/W+2 (Max: Respectable)]</p>
<p><b>Appearance:</b> In desperation, you return the goods and beg the other to dispel the curse. Taken by your handsome form, the other lifts the curse, letting you go with an admonition to do no more evil. [D1/S1]</p>`,
	},
	2263: {
		index: 2263,
		text: `<p>The other's fervor is unsettling—so unsettling that he turns over several carts in the market. You decide to do something about it.</p>
<p><b>No Skill:</b> You try to get the other to slow down—just a bit—to get him to arrange some kind of settlement with the merchants. As he just will not listen, you and the merchants decide that a different course must be pursued, and the other is taken to the square and beaten. [S1]</p>
<p><b>Bargaining and Evaluation:</b> You arrange with the merchants for the other to repair their carts and help them deliver goods. This arrangement works out well as the other applies his busy nature to a productive cause. [D1/Wisdom]</p>`,
	},
	2264: {
		index: 2264,
		text: `<p>A chatterbox is never desirable—but certainly not on a long voyage. You sail and sail with this busybody and not a one of the crew is happy about it. All are of agreement that he must be punished.</p>
<p><b>No Skill:</b> You recommend that he walk the plank, and all readily concur. Yet in the morning he's at the breakfast table again—still gabbing continually. Apparently he's a good swimmer. [S1/Seamanship]</p>
<p><b>Seamanship:</b> He is put in the crow's nest for the rest of the voyage, through storm and blistering heat. He tries to strike up conversations with the seagulls, but they soon abandon him as well. He eventually learns his lesson. [S1/<em>Respected</em>]</p>`,
	},
	2265: {
		index: 2265,
		text: `<p>The other is too much to keep up with and amazes you with his constant energy and tenacity. You realize, however, that he is not fulfilling his duties, but is building an elaborate scheme to murder his master. You seek to stop him, that he might be justly punished.</p>
<p><b>No Skill:</b> Alas, the slave's owner is not interested in hearing your baseless accusations against his favored servant. Soon after, you hear that the master was strangled in his sleep by an unknown assailant. [S1/<em>Grief Stricken</em>]</p>
<p><b>Wisdom:</b> By careful observation you develop irrefutable proof of the plans before you confront his master. The slave is executed and your great deed is praised by all who hear of it. [D1/S1/<em>Respected</em>]</p>`,
	},
	2266: {
		index: 2266,
		text: `<p>The other wishes you to have pity on him, for in his current state he is truly in ruins. You can tell that something is amiss with the other, but you're not sure what.</p>
<p><b>No Skill:</b> You decide that you must help and give him some coin to ease his strife. You later find that he was a charlatan—his false leg was a fake! You take the sham leg and beat him with it! Unfortunately, your coin has long been spent. [S1/W-1 (Min: Poor)/Acting and Disguise]</p>
<p><b>Acting and Disguise:</b> As you prepare to give the other some coin to easy his troubles, you notice that his false leg is a fake! You expose him as fraud and he is punished to the full extent of the law. [D1/<em>Respected</em>]</p>`,
	},
	2267: {
		index: 2267,
		text: `<p>A traveling prince has come into the town you visit, demanding to be treated according to his stature. The townspeople oblige but something about the prince strikes you as odd. The other is obviously disguised, and you seek to reveal his charade before any one is harmed.</p>
<p><b>No Skill:</b> Questioning him over dinner leads nowhere; but while you eat, you notice that he never does anything without watching the others first. He does not know proper table etiquette! You conspire to have him be the first to sample the monkey brains when they are brought to the table. When he begins to eat before the host is served, the murmurs trigger a cascade of discoveries. [S1/Courtly Graces]</p>
<p><b>Courtly Graces:</b> The more you speak with the other, the more it is clear that he is only a servant of some sort. By a clever line of questioning, you easily reveal him to be a charlatan. The townspeople deal with him swiftly for his ruse. [D1/Acting and Disguise]</p>`,
	},
	2268: {
		index: 2268,
		text: `<p>You are invited to a marriage of a friend and the eldest child of a potentate of a far land of which you have never heard. You are sure the betrothed is an imposter—and you swear to undo her disguise and bring her to humiliation.</p>
<p><b>No Skill:</b> You spend all of your time trying to figure it out. This makes your friend quite distressed, and you are asked to leave. But you will not stop searching for the truth in this, no matter what. [<em>Fated</em>]</p>
<p><b>Appearance, Seduction:</b> At the wedding, you are dressed in your finest and turn many eyes—particularly the one betrothed to your friend! "You are quite the important person, aren't you," the other says. "Perhaps you can take me away from this wretch?" You are aghast and expose the other to your friend immediately. Despite the good you have done, the taint of the scandal sticks to you. [D2/<em>Scorned</em>]</p>`,
	},
	2269: {
		index: 2269,
		text: `<p>After you have finished beating the other, he appears to be calmed somewhat. You later discover him using your punishment to earn pity from the Vizier.</p>
<p><b>No Skill:</b> You go before the Vizier to plead your case but he feels that you have been rather too harsh on this mad being. [S1/<em>Imprisoned</em>]</p>
<p><b>Bargaining and Evaluation:</b> You recognize the shrewdness of the other in turning adversity to advantage. You go to the Vizier and plead that the other is certainly not as mad as he seems, given how clearly he is turning his beating to his advantage. The Vizier sees your point and throws the other in the stocks. [D1/S1/Quick Thinking]</p>`,
	},
	2270: {
		index: 2270,
		text: `<p>When you finished administering your punishment, your victim eagerly follows you, wishing to be of service to you.</p>
<p><b>No Skill:</b> You cannot shake him and his constant ravings drive you from sanity! [D1/<em>Insane</em>]</p>
<p><b>Enduring Hardship:</b> You have pity on the poor wretch, who is obviously demented rather than truly evil. You take the other under your wing, and through much patience and understanding, you bring him back to just enough sensibility to again be part of society. [D2/S2/Scholarship/<em>Respected</em>]</p>`,
	},
	2271: {
		index: 2271,
		text: `<p>"It matters little how you try to punish me!" the other cries. "I have been through far worse than your torments in my time!"</p>
<p><b>No Skill:</b> You listen to his tale of woe and are dumbstruck by the magnitude of suffering revealed. You give the wretch some coin to ease his pain and depart him a changed being. [D1/S1/Storytelling]</p>
<p><b>Storytelling:</b> The other's tale is vast and wondrous—but it does not add up, even for the ravings of a madman. The more you listen, the more you realize that he is retelling stories of old, casting himself as the protagonists [changing just enough that any but the learned would not notice]. You trip him up during his tale revealing him as a mountebank of notorious reputation. You turn him in to the Vizier and are rewarded. [S2/W+1 (Max: Rich)]</p>`,
	},
	2272: {
		index: 2272,
		text: `<p>The other has managed to seat himself at the center of a vast web of criminal mischief, and you cannot stand by while he prospers. You swear justice will be done.</p>
<p><b>No Skill:</b> Unfortunately, the powerful are called powerful for a reason. You are unable to get past the other's layers of hangers-on and are forced to give up on your hopes. Perhaps a more indirect approach would have worked? [S1/Courtly Graces]</p>
<p><b>Stealth and Stealing:</b> You cannot get close to the other within the town, but you know him to be an avid gambler. You make sure he hears of a game you are running, and, with the help of friends of your own, you fleece him like a newborn lamb, so cleverly that he doesn't even suspect the game was rigged. [D1/W+1 (Max: Rich)]</p>`,
	},
	2273: {
		index: 2273,
		text: `<p>With a baleful glare, the other looks at you and spits out a curse. "You presume to punish me, little one? ME?!"</p>
<p><b>No Skill:</b> Try as you may, you cannot get the upper hand on the other. Now you are faced with a curse and your will is not strong enough to withstand it. [S1/<em>Accursed</em>]</p>
<p><b>Bargaining and Evaluation:</b> You regret your rash action, and fear for the consequences of the curse. You hold out your hands, palms up, hoping to slow the others actions. He slows and gives you a suspicious eye. You explain that you were wrong to accuse him, apologizing profusely. He agrees to share some insights from his life with you as you clearly need instruction in the ways of the world. [D1/Wisdom/<em>Fated</em>]</p>`,
	},
	2274: {
		index: 2274,
		text: `<p>Your soliloquy in the town square about the evils of the other comes so powerfully from within you that you barely notice as when the guards arrive to arrest you. It seems that the other is a favorite of the Vizier!</p>
<p><b>No Skill:</b> You plead your case before the court, but the Vizier does not believe you. He orders you cast into his dungeons. [S1/<em>Imprisoned</em>]</p>
<p><b>Seamanship:</b> The Vizier learns of your skills as a sailor. He has need of such a man as you. He agrees to spare your life in exchange for delivering a message across a particularly dangerous sea. [D1/Courtly Graces]</p>`,
	},
	2275: {
		index: 2275,
		text: `<p>You discover to your regret that the other was only pretending to be occupied. As you close in to strike a blow for justice, the other turns on you, quickly producing a blade.</p>
<p><b>No Skill:</b> You are not ready for this and he runs you through. He would have killed you but the city guard happens by and he flees. [D1/<em>Wounded</em>]</p>
<p><b>Appearance, Seduction:</b> The other stops short at your visage. He does not believe someone so fine would be thinking to do him harm. You agree saying that you were thought that he was an old friend and you wanted to surprise him. You part without further incident. [D2/Luck]</p>`,
	},
	2276: {
		index: 2276,
		text: `<p>You decide that the best way to punish the other is to relieve him of his paltry possessions. As you work to do so, you recognize that the other is a holy person.</p>
<p><b>No Skill:</b> You are thrown into remorse over what you have done and decide to go on a holy journey to cleanse yourself. [D-1/S1/Lose Piety/<em>Grief Stricken</em>/<em>On Pilgrimage</em>]</p>
<p><b>Acting and Disguise:</b> Quickly disguising yourself as a philanthropist, you return the coins. The other takes it as a sign of Allah's compassion and resumes his pilgrimage. You praise Allah for allowing you atonement for your crime. [D1/S1/Piety]</p>`,
	},
	2277: {
		index: 2277,
		text: `<p>Reluctantly, the other draws a sword and faces you. "I have been trying to avoid any further bloodshed in my life, but you leave me no choice."</p>
<p><b>No Skill:</b> Begging the forgiveness of Allah, the other proceeds to thrash you soundly. [D1/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> He is quite a skilled swordsman and he does get past your defenses a few times. You end up the better, taking him down in the end. This is more punishment than you intended, but Allah is still served. [D1/S1/Enduring Hardship]</p>
<p><b>Quick Thinking:</b> Realizing you are no match for this swordsman, you quickly point out that you may have been sent by Allah to test his resolve. The other does not doubt you and puts away the sword, allowing you to go on your way. [D1/S1/Beguiling]</p>`,
	},
	2278: {
		index: 2278,
		text: `<p>The offensive one cries out and others rush to see what is the cause of the cries.</p>
<p><b>No Skill:</b> The other's beguiling ways are most convincing, and the crowd does not listen to your pleas regarding his evilness. They beat you and do not hesitate to rob you as well. [D2/S1/W-2 (Min: Penniless)/Beguiling/<em>Wounded</em>]</p>
<p><b>Courtly Graces, Beguiling:</b> As you continue the beating, you calmly point out to the crowd the crimes of the other. They join you in ministering justice. [D1/S2/Acting and Disguise]</p>`,
	},
	2279: {
		index: 2279,
		text: `<p>The other does not resist your punishment. He sees the error of his ways and accepts all that will come to him.</p>
<p><b>No Skill:</b> You are awed by the other's holiness. You ask him to teach you of Allah's wonders. He agrees, if you will give alms. [D2/W-1 (Min: Poor)/Piety]</p>
<p><b>Piety:</b> You are seen by all as a messenger from Allah. All approve of your justice. [D1/S1/<em>Respected</em>]</p>`,
	},
	2280: {
		index: 2280,
		text: `<p>After you have finished beating the other, he appears humbled.</p>
<p><b>No Skill:</b> You leave him to meditate on his deeds, not realizing that he would follow and rob you in your sleep. [S1/W-2 (Min: Penniless)]</p>
<p><b>Courtly Graces:</b> His humility reminds you of something. Giving it some thought, you realize that he is a holy man who has lost his way. You offer to help him make a pilgrimage to cleanse his soul. [D2/S2/W-1 (Min: Poor)/Wisdom/<em>On Pilgrimage</em>]</p>`,
	},
	2281: {
		index: 2281,
		text: `<p>You decide that the rich are best punished by making them poor. You decide to frame the other in an elaborate plot to overthrow the Sultan. But your plan is found out and the Sultan decides to punish you both. You share a dungeon cell together. [D1/S1/W-3 (Min: Penniless)/Bargaining and Evaluation/<em>Imprisoned</em>]</p>`,
	},
	2282: {
		index: 2282,
		text: `<p>The other is wealthy beyond your dreams. There seems to be no way to punish him for his deeds. You cannot get past his guards, and you cannot muster the connections to discredit him. You decide that your only hope is to wait in the woods to try to catch him hunting.</p>
<p><b>No Skill:</b> You wait for weeks and finally decide to give up on the endeavor. [S1/Enduring Hardship]</p>
<p><b>Enduring Hardship:</b> You wait for weeks but the other never seems to actually go hunting. Your time is still well-spent as you get to know the area quite well. [D1/Wilderness Lore]</p>`,
	},
	2283: {
		index: 2283,
		text: `<p>The other is planning to transfer many fine vases from one of his villas to another. You think that it would be a grand punishment to destroy his finery.</p>
<p><b>No Skill:</b> You arrange for a livestock stampede as the other's wagons pass a farm. The horses are spooked and the cart is overturned in the ruckus, destroying the vases. You can't help but to gloat. Unfortunately, your information was wrong: the other was giving the vases to the Sultan as a gift. The Sultan punishes you soundly for your vandalism. [D1/<em>Enslaved</em>]</p>
<p><b>Bargaining and Evaluation:</b> You plan to meet the other's cart in the woods and have hired thugs overturn the shipment. On consideration, you make another twist in your plan and instead threaten the other with the action unless he gifts the vases to the Sultan in both your names. He relents and the Sultan is most pleased with the gesture. [S1/<em>Vizier</em>]</p>`,
	},
	2284: {
		index: 2284,
		text: `<p>Your attempt to punish other is easily thwarted.</p>
<p><b>No Skill:</b> When the other has you at his mercy, you are beaten and tortured until he has satisfied his wicked desires. [D1/S1/Beguiling/<em>Crippled</em>]</p>
<p><b>Weapon Use:</b> The other has the best of you with words, but you are sure to get the best of him with the blade. You attack with great skill, but you quickly realize that you are facing your equal [or perhaps superior] and you quickly withdraw. [D1/Wisdom]</p>`,
	},
	2285: {
		index: 2285,
		text: `<p>You decide that the best punishment that you can deliver is to send the other to his grave.</p>
<p><b>No Skill:</b> As you are looting his body, a shadow looms over you. The one you defeated has a loyal companion who is prepared to take revenge! He has caught you unaware and you are at his mercy. [D1/W-3 (Min: Penniless)/<em>Enslaved</em>]</p>
<p><b>Acting and Disguise:</b> You realize that the other you have defeated has a companion who is surely going to seek revenge. You quickly don the other's robes and muffle your face. When the companion comes, you pretend to be his friend and report that though you have slain your foe, you are afraid that he was a leper and now you are infected. The companion collects food, money, and a cart and horse for you to travel to a leper colony. You bid him a fine farewell as you depart with your booty. [S2/W+2 (Max: Respectable)/Acting and Disguise]</p>`,
	},
	2286: {
		index: 2286,
		text: `<p>The other apparently chooses not to face you. He instead disappears into a maze of buildings, leaving you with nothing but your righteous anger. [D2]</p>`,
	},
	2287: {
		index: 2287,
		text: `<p>The other is looking to bring fine carpets from Persia and Arabia to the rich, if less cultured, nations to the west. The other is certainly cunning, but you feel as though your skills could make the other's endeavors that much more successful.</p>
<p><b>No Skill:</b> You suggest an alliance—one where you can help to gather buyers. The other decides to try you out and you do make a few sales. It is not enough for the other to wish a permanent partnership, however. [S1/W+1 (Max: Rich)/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> You use some contacts that you've gathered in your travels to make some sales before you even talk to the other. Bringing him some business right from the start is most impressive, and he agrees to partner with you and you have a successful run of it. [D1/S1/W+2 (Max: Rich)/<em>Respected</em>]</p>`,
	},
	2288: {
		index: 2288,
		text: `<p>The other has a failing carpet-selling business. You think that you can expand his business outside of his local region. There are but a few routes to the rich, if less cultured, nations of the west, and you know of good ways to use them.</p>
<p><b>No Skill:</b> You arrange with the other to create trade arrangements. Business is good. [D1/W+1 (Max: Princely)/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> The other sees the wisdom of your plans and agrees to do business with you, teaching the business of trade by sea as well. [D1/W+2 (Max: Princely)/Seamanship]</p>`,
	},
	2289: {
		index: 2289,
		text: `<p>The other's carpet-selling business is failing, though his carpets are wondrous. You think that perhaps you can help.</p>
<p><b>No Skill:</b> There are only a few captains who can truly be trusted to deliver cargo in a safe and profitable manner. One of them owes you a favor. You call in on the favor to do a delivery run cheaply, making the other a great deal of coin. Your share is considerable, but with no more favors, you decide that it's best to get out now—much to the chagrin of your partner. [D1/W+2 (Max: Princely)/<em>Pursued</em>]</p>
<p><b>Seamanship:</b> You are able to devise a plan to save many days in shipping time—making the endeavor far more profitable. Your new partner is pleased. [D1/W+3 (Max: Princely)/Bargaining and Evaluation]</p>`,
	},
	2290: {
		index: 2290,
		text: `<p>You hope that this other might use his wealth and influence to aid you, but for now, you will present yourself as one wishing to help him.</p>
<p><b>No Skill:</b> The other enjoys making you grovel for a bit and lets you assist him in some of his dealings. He shortly discovers that your true end is to take advantage of his good position. Righteous or not in your process, the other is still taken aback by this and dismisses you. [D1/W+1 (Max: Rich)/<em>Fated</em>]</p>
<p><b>Seamanship:</b> As you speak, you tell the other of your many travels across the oceans. The other is delighted and impressed by your adventures. He demands that you tell tales of your journeys and after an evening of sharing tales, he agrees to assist you with some portion of the monies under his command. [D1/S1/W+2 (Max: Rich)/Storytelling]</p>`,
	},
	2291: {
		index: 2291,
		text: `<p>The other mocks your offered assistance. "What use have I for such an inexperienced boob?"</p>
<p><b>No Skill:</b> You are embarrassed to be rejected by one of such low standing and meekly make your way out of town. [D1/<em>Scorned</em>]</p>
<p><b>Seduction:</b> "Perhaps I have not made clear all of the ways that I can be of assistance," you say. The other finds your offer far more tempting and agreeable. [S1/<em>Beloved</em>]</p>
<p><b>Bargaining and Evaluation:</b> "Clearly, sir, you are not in need of any help from anyone. That said, you are also not so foolish as to fail to see how you can take advantage of another. Let me make my offer and take the risk of losing to your skills." With your consummate ability you convince the other that your advice is of great value. The other takes your advice and your rewards for service are fine indeed. [D1/W+1 (Max: Rich)/<b>Treasure</b>]</p>`,
	},
	2292: {
		index: 2292,
		text: `<p>The other is delighted by your generous offer. He invites you to his home for the evening meal.</p>
<p><b>No Skill:</b> You enjoy a wondrous evening in his home. Your host welcomes you to explore the fine collection of art and literature in his stewardship. You find a number of intriguing volumes, and your host makes of them a fine gift. [D1/Scholarship/<b>Treasure</b>]</p>
<p><b>Luck:</b> The other introduces you to his wife, and you realize that she is your cousin! You never hoped to see her again. You happily tell each other your tales and journeys and as you are a relation, the other is pleased to share with you his wisdom from his many journeys. [D2/Wilderness Lore/<em>Fated</em>]</p>`,
	},
	2293: {
		index: 2293,
		text: `<p>The other laughs when you offer him your aid. "You are nothing but a beggar in my eyes, little one!" He continues to laugh as he turns his back to you.</p>
<p><b>No Skill:</b> Others around are attracted by the other's laughter, and soon they join in mocking you. [S1/<em>Scorned</em>]</p>
<p><b>Wilderness Lore:</b> The other turns and bumps a short-tempered magician, who transforms him into an ape! Your experience in the jungles has shown you the herbs needed to reverse this spell. You make the concoction for the ape and when turned human again, he showers you with gifts and apologies. [D2/S2/Beguiling/<b>Treasure</b>]</p>`,
	},
	2294: {
		index: 2294,
		text: `<p>You notice a mysterious glimmer in the eye of the other as you offer your assistance. There may be more to this being than meets the eye.</p>
<p><b>No Skill:</b> You shrug off your intuition and continue with your conversation. Suddenly you awaken to discover that summer has ended and winter begun! You're not sure where you are, but you are sure that you need to find some clothes fast! [D2/S1/W-4 (Min: Penniless)/Wilderness Lore/Have another player move you to any land space]</p>
<p><b>Seduction:</b> You find yourself strangely attracted to the other, though you cannot be sure why. When your senses return, you discover that he has cast a charm upon you! [D-1/S2/<em>Ensorcelled</em>]</p>
<p><b>Scholarship:</b> You realize that this is a magician in disguise! You quickly avert your gaze before he can charm you with his magic. [D1/S1/Quick Thinking]</p>`,
	},
	2295: {
		index: 2295,
		text: `<p>You have no doubt that the other is wealthy, though you do have some doubts as to how or why. You think that the best way to learn his secrets is to offer to be of service to him.</p>
<p><b>No Skill:</b> After a time you find that the other is clearly ensorcelled. Lest he turn his ire upon you, best you give of yourself generously. When the opportunity shows itself, you sneak off with the knowledge you've gained, but little else. [D1/S1/W-2 (Min: Poor)/Magic/Wilderness Lore]</p>
<p><b>Seamanship:</b> You aid the other gaining luxury passage to the East. He thanks you by telling you his tale. Cursed by the Sultan's evil Vizier, even with his great wealth the other can never travel back to his home in the depths of the sea. You comfort the other and he tells you of the sea's secrets. [D1/S1/Storytelling/Opportunity to enter the Undersea Kingdom]</p>`,
	},
	2296: {
		index: 2296,
		text: `<p>You find the other sitting on a stone in a river, rocking back and forth and muttering in a strange language. You try to make out some of what he is saying.</p>
<p><b>No Skill:</b> Whatever he is saying, you don't think it's a real language. Soon you feel woozy. You try to get out some questions but you just begin to mutter. For a fleeting moment you realize that you are muttering in the same strange tongue as the other, then all goes black. [D1/Magic/<em>Ensorcelled</em>/<em>Insane</em>]</p>
<p><b>Magic:</b> You understand enough of what he is saying to know that you need to flee immediately! Before you can escape, your mind ceases as hidden secrets you were not meant to know are revealed to you! [D2/<em>Insane</em>]</p>`,
	},
	2297: {
		index: 2297,
		text: `<p>The other was once a renowned explorer, but something he saw in some distant land has permanently unhinged his mind. You try to lead him down the path of sanity just long enough to gain some insight into the distant lands he's traveled.</p>
<p><b>No Skill:</b> You have no luck in learning anything about distant lands, but the other's tales do inspire you greatly. [S2/Storytelling/<em>Determined</em>]</p>
<p><b>Wilderness Lore:</b> From time to time the other utters a phrase or two that make sense. After days of speaking with the mad bring, you piece together enough to discover the path to an ancient wonder. [D1/Opportunity to enter any Place of Power]</p>`,
	},
	2298: {
		index: 2298,
		text: `<p>You stop to ask for directions to the next town, but clearly the one you are asking is quite mad.</p>
<p><b>No Skill:</b> You are sure that the other has some kind of secret to share. No one gets this mad without some great happening in his past. You query him further and further until you are quite spent. [D1]</p>
<p><b>Scholarship:</b> Just when you start to make sense from the ramblings of the other, his keeper comes to collect him. He calls the other by a nickname—one that you recognize from legends of ancient places. You use this information to press further and in a moment of lucidity, the other gives you just enough information that you can piece together the puzzle. [D2/Opportunity to enter any Place of Power]</p>`,
	},
	2299: {
		index: 2299,
		text: `<p>"You are trying to deceive me? Mortal, I am foremost of a race of deceivers and tricksters! However, your audacity amuses me and I will be less harsh on you than you deserve." [S1/<em>Wounded</em>]</p>`,
	},
};
